head.script:
scwin.mainClose = function(title) {
    var result = confirm("close?");
    if (result) {
        return true;
    } else {
        return false;
    }
};
scwin.createWindowTest = function(title) {
    wc1.createWindow(title, "", "", "windowTitle", title, "newWindow", scwin.mainClose, null, null);
    //wc1.createWindow( title , iconUrl , src , windowTitle , windowId , openAction , closeAction , windowTooltip, null)
};
scwin.wc1_onbeforecloseall = function() {
    debugger;
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc1_vertical').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc1_horizontal').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc1_cascade').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('wc1_subWindow0_header')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wc1_subWindow0').height() > 250", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    scwin.createWindowTest("main");
    //scwin.createWindowTest("aa");
    //scwin.createWindowTest("bb");
    //scwin.createWindowTest("cc");
}
